+		if call.Name != toolSearchToolName {
+			continue
+		}
+		result := messages[i+1]
+		if result.Role != llm.RoleTool || result.ToolCallID == nil || *result.ToolCallID != call.ID || result.Content.Text == nil {
+			continue
+		}
+		names = append(names, extractDiscoveredNames(*result.Content.Text)...)
+	}
+	return names
